    // Need to promote - need write lock
    c.mu.RUnlock()

    c.mu.Lock()
    // Check again in case it changed
    elem, ok = c.items[key]
    if !ok {
        c.mu.Unlock()
        return "", false
    }
    c.order.MoveToFront(elem)
    val := elem.Value.(*entry).value
    c.mu.Unlock()
    return val, true
}

func (c *Cache) Put(key string, value string) {
    c.mu.Lock()
    defer c.mu.Unlock()

    if elem, ok := c.items[key]; ok {
        // Update existing entry
        elem.Value.(*entry).value = value
        c.order.MoveToFront(elem)
        return
    }

    // Evict if full
    if c.order.Len() >= c.capacity {
        back := c.order.Back()
        if back != nil {
            e := back.Value.(*entry)
            delete(c.items, e.key)
            c.order.Remove(back)
        }
